'use strict';

// Generated by Clause Sonnet 5.5 / Refactored by HellXCore
// The installed apps on Linux, from their .desktop files (the freedesktop Desktop Entry spec):
// what launch.js offers when you ask her to open one, and the names apps-linux.js shows 
// for the windows open. The Linux counterpart of Windows' Get-StartApps.

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawn } = require('node:child_process');

const CACHE_MS = 10 * 60 * 1000; // installed apps hardly change

let cache = null; // { at, entries }

// where applications/*.desktop live: your own, the system's, Flatpak's and Snap's
function applicationDirs(env = process.env, home = os.homedir()) {
  const dataHome = env.XDG_DATA_HOME || path.join(home, '.local', 'share');
  const dataDirs = (env.XDG_DATA_DIRS || '/usr/local/share:/usr/share').split(':').filter(Boolean);
  const extra = ['/var/lib/flatpak/exports/share', path.join(home, '.local', 'share', 'flatpak', 'exports', 'share'), '/var/lib/snapd/desktop'];
  return [...new Set([dataHome, ...dataDirs, ...extra])].map((d) => path.join(d, 'applications'));
}

// "ru_RU.UTF-8@euro" -> ['ru_RU', 'ru']: the keys Name[...] may be found under
function localeKeys(env = process.env) {
  const raw = env.LC_ALL || env.LC_MESSAGES || env.LANG || '';
  const base = raw.split('.')[0].split('@')[0];
  if (!base || base === 'C' || base === 'POSIX') return [];
  return [...new Set([base, base.split('_')[0]])];
}

const unescape = (v) => v.replace(/\\(s|n|t|r|\\)/g, (_, c) => ({ s: ' ', n: '\n', t: '\t', r: '\r', '\\': '\\' }[c]));

// the [Desktop Entry] group of a .desktop file, as { key: value } (Name[xx] kept as is)
function parse(text) {
  const out = {};
  let inside = false;
  for (const raw of String(text).split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    if (line.startsWith('[')) {
      if (inside) break; // the next group (an Action): not the app itself
      inside = line === '[Desktop Entry]';
      continue;
    }
    if (!inside) continue;
    const eq = line.indexOf('=');
    if (eq > 0) out[line.slice(0, eq).trim()] = unescape(line.slice(eq + 1).trim());
  }
  return out;
}

function onPath(cmd, env = process.env) {
  if (!cmd) return true;
  const exists = (f) => {
    try {
      fs.accessSync(f, fs.constants.X_OK);
      return true;
    } catch {
      return false;
    }
  };
  if (path.isAbsolute(cmd)) return exists(cmd);
  return (env.PATH || '').split(':').some((d) => d && exists(path.join(d, cmd)));
}

// The entry's id, as the desktop knows it: the path under applications/, "/" as "-"
// (kde/foo.desktop is "kde-foo.desktop"). A file found in an earlier directory wins.
function scan({ env = process.env, home = os.homedir() } = {}) {
  const keys = localeKeys(env);
  const desktops = String(env.XDG_CURRENT_DESKTOP || '').split(':').filter(Boolean);
  const byId = new Map();
  const walk = (root, dir, depth) => {
    let items = [];
    try {
      items = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of items) {
      const full = path.join(dir, e.name);
      if (e.isDirectory() && depth < 3) {
        walk(root, full, depth + 1);
      } else if (e.name.endsWith('.desktop')) {
        const id = path.relative(root, full).split(path.sep).join('-');
        if (byId.has(id)) continue;
        let fields;
        try {
          fields = parse(fs.readFileSync(full, 'utf8'));
        } catch {
          continue;
        }
        byId.set(id, { id, file: full, fields });
      }
    }
  };
  for (const dir of applicationDirs(env, home)) walk(dir, dir, 0);

  const entries = [];
  for (const { id, file, fields: f } of byId.values()) {
    if (f.Type !== 'Application' || f.NoDisplay === 'true' || f.Hidden === 'true' || !f.Exec) continue;
    const only = (f.OnlyShowIn || '').split(';').filter(Boolean);
    const not = (f.NotShowIn || '').split(';').filter(Boolean);
    if (only.length && desktops.length && !only.some((d) => desktops.includes(d))) continue;
    if (not.some((d) => desktops.includes(d))) continue;
    if (!onPath(f.TryExec, env)) continue;
    const name = keys.map((k) => f[`Name[${k}]`]).find(Boolean) || f.Name;
    if (!name) continue;
    // generic: the name without a translation ("Konsole" for "Консоль"), also what you may say
    entries.push({ id, file, name, generic: f.Name || name, exec: f.Exec, wmClass: f.StartupWMClass || '' });
  }
  return entries;
}

// [{ id, file, name, generic, exec, wmClass }], kept for a while
function list(options) {
  if (!options && cache && Date.now() - cache.at < CACHE_MS) return cache.entries;
  const entries = scan(options);
  if (!options) cache = { at: Date.now(), entries };
  return entries;
}

const base = (id) => String(id || '').replace(/\.desktop$/, '').toLowerCase();

// The entry a window belongs to: by the desktop file KWin reports for it, else by its window class.
function forWindow({ app = '', cls = '' } = {}, entries = list()) {
  const a = base(app);
  const c = String(cls).toLowerCase();
  return entries.find((e) => a && base(e.id) === a)
    || entries.find((e) => c && e.wmClass && e.wmClass.toLowerCase() === c)
    || entries.find((e) => c && base(e.id) === c)
    || null;
}

// the Exec line without its field codes (%f %U...), as [command, ...args]; "%%" is a literal %
function splitExec(exec) {
  const args = [];
  let cur = '';
  let quote = null;
  let has = false;
  const s = String(exec);
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) {
      if (ch === '\\' && i + 1 < s.length) cur += s[++i];
      else if (ch === quote) quote = null;
      else cur += ch;
    } else if (ch === '"' || ch === "'") {
      quote = ch;
      has = true;
    } else if (/\s/.test(ch)) {
      if (has || cur) args.push(cur);
      cur = '';
      has = false;
    } else if (ch === '%' && i + 1 < s.length) {
      const code = s[++i];
      if (code === '%') cur += '%';
      has = has || cur !== '';
    } else {
      cur += ch;
    }
  }
  if (has || cur) args.push(cur);
  return args.filter((a, i) => i === 0 || a !== '');
}

// resolves when the process started, rejects when it could not (no such command)
function startDetached(cmd, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, { detached: true, stdio: 'ignore' });
    child.once('error', reject);
    child.once('spawn', () => {
      child.unref();
      resolve();
    });
  });
}

// Opens one of the apps listed (never anything else): through the desktop's own launcher (gio,
// gtk-launch, KDE's kioclient), which takes care of its environment, else its Exec line itself.
async function launch(id, { entries = list(), start = startDetached } = {}) {
  const entry = entries.find((e) => e.id === id);
  if (!entry) throw new Error('not found');
  const attempts = [
    ['gio', ['launch', entry.file]],
    ['gtk-launch', [entry.id]],
    ['kioclient6', ['exec', entry.file]],
    ['kioclient5', ['exec', entry.file]],
  ];
  for (const [cmd, args] of attempts) {
    try {
      await start(cmd, args);
      return;
    } catch (err) {
      if (err.code !== 'ENOENT') throw err; // it exists but failed: not for another one to retry
    }
  }
  const [cmd, ...args] = splitExec(entry.exec);
  if (!cmd) throw new Error('no command');
  await start(cmd, args);
}

module.exports = { list, scan, parse, forWindow, launch, splitExec, applicationDirs, localeKeys };
